import {createLedger,activeSources,addAnalysis,addSource,reviseSource,removeSource,reconstruct,reconstructionChanges} from './reconstruction-core.js';
import {demoLedger,correctDemoDate} from './reconstruction-demo.js';
import {reconstructionCopy} from './reconstruction-copy.js';
import {mobileCopy} from './mobile-copy.js';
import {productCopy} from './product-copy.js';
import {WORKSPACE_KEY,restoreWorkspace,workspaceJSON,handoffText} from './reconstruction-workspace.js';
import {PROVIDERS,connectionConfig,customConnection,customEndpoint} from './provider-client.js';
import {reconstructOnDevice,CONNECTION_SAMPLE,assertConnectionSample} from './reconstruction-model.js';
import {isAndroid,deviceFetch,saveFile} from './device-client.js';

const root=document.querySelector('#reconstruction-app'),status=document.querySelector('#reconstruction-status');
const labels={zh:'简体中文',en:'English',es:'Español',fr:'Français',ja:'日本語',ko:'한국어'};
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const params=new URL(location.href).searchParams;
function readPref(key,fallback){try{return localStorage.getItem(key)||fallback;}catch{return fallback;}}
function setPref(key,value){try{localStorage.setItem(key,value);}catch{}}
const requested=params.get('lang')||readPref('care-notes.lang',navigator.language.split('-')[0]);
let lang=labels[requested]?requested:'en',sampleLang=lang,tab='capture';
let mode=params.get('mode')==='demo'?'demo':'own',own=createLedger(),storageOK=true,broken='';
try{const raw=localStorage.getItem(WORKSPACE_KEY);if(raw){broken=raw;own=restoreWorkspace(raw);broken='';}}catch{storageOK=false;}
let ownRaw=readPref(WORKSPACE_KEY,'');
let example=demoLedger(lang),demoModified=false,ledger=mode==='demo'?example:own,result=reconstruct(ledger),changes=null,editing='',corrected=false,revision=0,questionLimit=3,reviewed=false;
let connection={provider:'openai',model:'',apiKey:''};
try{const p=JSON.parse(readPref('care-notes.connection.v1','{}'));if(['openai','deepseek','custom'].includes(p.provider))connection={provider:p.provider,model:typeof p.model==='string'?p.model.slice(0,128):'',apiKey:'',...(p.provider==='custom'?{baseUrl:typeof p.baseUrl==='string'?p.baseUrl.slice(0,1000):'',format:p.format==='responses'?'responses':'chat'}:{})};}catch{}
let configured=false,checked=false,busy=false,testConsent=false,sendConsent=false,controller=null,noticeTimer;
const drafts={};
const t=()=>reconstructionCopy[lang],m=()=>mobileCopy[lang],p=()=>productCopy[lang];
const method=()=>ledger.analyses.at(-1)?.method||'manual';
const hasEdits=()=>Boolean(editing||drafts.new?.trim());
const notice=message=>{clearTimeout(noticeTimer);status.textContent=message;noticeTimer=setTimeout(()=>{status.textContent='';},12000);};
const button=(action,label,attrs='')=>`<button type="button" data-action="${action}" ${attrs}>${esc(label)}</button>`;
const sourceName=id=>activeSources(ledger).find(s=>s.id===id)?.author||id;
const sourceLink=id=>`<a href="#source-${esc(id)}" data-source="${esc(id)}">${esc(p().originals)} · ${esc(id)}</a>`;
function timeLabel(time){if(!time.start)return t().unknownTime;const f=new Intl.DateTimeFormat(t().locale,{dateStyle:'medium',timeStyle:'short'});return `${f.format(new Date(time.start))} — ${f.format(new Date(time.end))} (${Intl.DateTimeFormat().resolvedOptions().timeZone})`;}
function localTimestamp(){const now=new Date(),minutes=-now.getTimezoneOffset();return new Date(now.getTime()+minutes*60000).toISOString().slice(0,-1)+(minutes<0?'-':'+')+String(Math.floor(Math.abs(minutes)/60)).padStart(2,'0')+':'+String(Math.abs(minutes)%60).padStart(2,'0');}
function persist(){if(mode==='demo'){example=ledger;return;}own=ledger;if(broken)return;try{if((localStorage.getItem(WORKSPACE_KEY)||'')!==ownRaw)throw Error('storage_conflict');const next=workspaceJSON(ledger);localStorage.setItem(WORKSPACE_KEY,next);ownRaw=next;storageOK=true;}catch{storageOK=false;}}
function update(next){if(workspaceJSON(next).length>4000000)throw Error('too_large');const before=result;ledger=next;result=reconstruct(ledger,{questionLimit});changes=reconstructionChanges(before,result);revision++;reviewed=false;sendConsent=false;if(mode==='demo')demoModified=true;persist();render();}
function clearDrafts(){for(const k of Object.keys(drafts))delete drafts[k];editing='';}
function route(next){tab=next;render();window.scrollTo({top:0,behavior:'instant'});}
function destination(){try{return connection.provider==='custom'?customEndpoint(connection.baseUrl,connection.format):PROVIDERS[connection.provider].origin+PROVIDERS[connection.provider].path;}catch{return '—';}}
function direct(){return isAndroid()||connection.provider==='custom'||!configured;}
function transportText(){return isAndroid()?p().native:direct()?p().direct:p().proxy;}
function saveConnection(){const {apiKey,...pref}=connection;setPref('care-notes.connection.v1',JSON.stringify(pref));}
function resetConsent(){checked=false;testConsent=false;sendConsent=false;}
function settings(){const c=m(),u=p();return `<section class="panel"><h2>${esc(c.setup)}</h2><fieldset ${busy?'disabled':''}>
<label>${esc(c.provider)}<select id="provider"><option value="openai" ${connection.provider==='openai'?'selected':''}>OpenAI</option><option value="deepseek" ${connection.provider==='deepseek'?'selected':''}>DeepSeek</option><option value="custom" ${connection.provider==='custom'?'selected':''}>${esc(u.custom)}</option></select></label>
${connection.provider==='custom'?`<label>${esc(u.format)}<select id="api-format"><option value="chat" ${connection.format==='chat'?'selected':''}>${esc(u.chat)}</option><option value="responses" ${connection.format==='responses'?'selected':''}>${esc(u.responses)}</option></select></label><label>${esc(u.baseUrl)}<input id="base-url" type="url" value="${esc(connection.baseUrl)}" maxlength="1000" placeholder="https://…/v1" autocomplete="off" autocapitalize="none" spellcheck="false"></label><p class="meta">${esc(u.baseHint)}</p>`:''}
<label>${esc(c.model)}<input id="model" value="${esc(connection.model)}" maxlength="128" autocomplete="off" autocapitalize="none" spellcheck="false"></label><p class="meta">${esc(c.modelHint)}</p>
<label>${esc(c.key)}<input id="api-key" type="password" value="${esc(connection.apiKey)}" maxlength="512" autocomplete="off" autocapitalize="none" spellcheck="false"></label><p class="meta">${esc(u.keyHint)}</p>
<p class="meta" id="destination">${esc(c.destination)}: ${esc(destination())}</p><p class="meta">${esc(transportText())}</p>
<label class="consent"><input id="test-consent" type="checkbox" ${testConsent?'checked':''}><span>${esc(c.testConsent)}</span></label>
<div class="toolbar">${button('test',busy?t().busy:c.test,`class="primary" ${busy?'disabled':''}`)}${button('disconnect',c.disconnect)}</div></fieldset>${checked?`<p class="success">${esc(c.checked)}</p>${button('capture',u.goCapture)}`:''}</section>`;}
function aiControls(){const u=p(),c=m(),sources=activeSources(ledger);return `<div class="analysis-action">${checked?`<label class="consent"><input id="send-consent" type="checkbox" ${sendConsent?'checked':''} ${busy?'disabled':''}><span>${esc(u.sendConsent)}</span></label><p class="meta">${esc(c.destination)}: ${esc(destination())}</p><p class="meta">${esc(transportText())}</p>${button('analyse',busy?t().busy:c.send,`class="primary wide" ${busy||!sources.length?'disabled':''}`)}`:`${button('settings',u.connect,'class="primary wide"')}<p class="meta">${esc(u.connectionNeeded)}</p>`}${busy?button('stop',u.cancelRequest):''}</div>`;}
function sourceCard(s){const c=t();return `<article class="source" id="source-${esc(s.id)}"><div class="source-head"><h3>${esc(s.author)}</h3><span class="meta">${esc(c.version)} ${s.version}</span></div>${editing===s.id?`<form id="edit-source" data-id="${esc(s.id)}"><label>${esc(c.sources)}<textarea name="text" required maxlength="5000">${esc(drafts[s.id]??s.text)}</textarea></label><div class="toolbar"><button type="submit" class="primary">${esc(c.save)}</button>${button('cancel',c.cancel)}</div></form>`:`<p class="original">${esc(s.text)}</p><div class="toolbar compact">${button('edit',c.edit,`data-id="${esc(s.id)}"`)}${button('delete',p().delete,`class="quiet" data-id="${esc(s.id)}" ${busy?'disabled':''}`)}</div>`}${result.unanalysed.includes(s.id)?`<p class="meta">${esc(c.pending)}</p>`:''}<details><summary>${esc(c.history)}</summary><p class="meta">${esc(s.id)}</p>${ledger.sources.find(x=>x.id===s.id).versions.map(v=>`<p class="meta">${esc(c.version)} ${v.version}</p><blockquote>${esc(v.text)}</blockquote>`).join('')}</details></article>`;}
function capture(){const c=t(),u=p(),sources=activeSources(ledger);return `<section class="panel composer"><h2>${esc(c.add)}</h2><form id="add-source"><label class="sr-only" for="new-text">${esc(c.add)}</label><textarea id="new-text" name="text" maxlength="5000" required placeholder="${esc(u.placeholder)}">${esc(drafts.new??'')}</textarea><label>${esc(m().author)}<input name="author" maxlength="80" value="${esc(drafts.author??'')}"></label><div class="toolbar"><button type="submit" class="primary" ${sources.length>=40?'disabled':''}>${esc(u.save)}</button>${button('review',u.ready)}</div></form><p class="meta">${esc(mode==='demo'?m().exampleOnly:storageOK?u.local:m().storageFailed)}</p></section>${sources.length?`<section class="panel">${aiControls()}</section><section class="panel"><h2>${esc(c.sources)} <span class="count">${sources.length}</span></h2>${[...sources].reverse().map(sourceCard).join('')}</section>`:`<section class="panel empty"><p>${esc(u.emptyReview)}</p>${button('demo',u.startDemo)}</section>`}`;}
function changesPanel(){if(!changes||![changes.withdrawnClaims.length,changes.withdrawnRelations.length,changes.addedClaims.length,changes.updatedClaims.length].some(Boolean))return '';const c=t();return `<section class="panel changes"><h2>${esc(c.changes)}</h2><div class="changes-grid"><div><b>${changes.withdrawnClaims.length}</b>${esc(c.withdrawn)}</div><div><b>${changes.withdrawnRelations.length}</b>${esc(c.linksWithdrawn)}</div><div><b>${changes.addedClaims.length+changes.updatedClaims.length}</b>${esc(c.added)}</div></div>${changes.withdrawnClaims.map(x=>`<blockquote class="retired">${esc(x.quote)}</blockquote>`).join('')}${changes.updatedClaims.map(x=>`<blockquote>${esc(x.after.quote)}<p class="meta">${esc(timeLabel(x.before.time))} → ${esc(timeLabel(x.after.time))}</p></blockquote>`).join('')}</section>`;}
function review(){const c=t(),u=p(),sources=activeSources(ledger),claims=new Map(ledger.analyses.flatMap(a=>a.claims.map(x=>[x.key,x])));return `${mode==='demo'?`<section class="panel demo-action"><p>${esc(c.intro)}</p><div class="toolbar">${button('correct',corrected?c.corrected:c.correct,`class="primary" ${corrected||sources.find(s=>s.id==='e2')?.version!==1?'disabled':''}`)}${button('reset',c.reset)}</div></section>`:''}${changesPanel()}${!sources.length?`<section class="panel empty"><p>${esc(u.emptyReview)}</p>${button('demo',u.startDemo)}${button('capture',u.goCapture)}</section>`:`${result.unanalysed.length?`<p class="note">${esc(result.claims.length?u.pending:u.manual)}</p>`:''}<section class="panel"><h2>${esc(c.accounts)}</h2>${result.claims.length?[...result.claims].sort((a,b)=>(a.time.start||'z').localeCompare(b.time.start||'z')).map(x=>`<article class="account"><h3>${esc(sourceName(x.sourceId))}</h3><p class="meta">${esc(c.basis[x.basis])}</p><blockquote>${esc(x.quote)}</blockquote><p class="meta">${esc(timeLabel(x.time))}</p>${x.polarity==='unknown'?`<p class="note">${esc(c.unknownFact)}</p>`:''}${sourceLink(x.sourceId)}</article>`).join(''):sources.map(s=>`<article class="account"><h3>${esc(s.author)}</h3><blockquote>${esc(s.text)}</blockquote>${sourceLink(s.id)}</article>`).join('')}</section>
${result.relations.length?`<section class="panel"><h2>${esc(c.relations)}</h2>${result.relations.map(r=>`<article class="relationship ${r.status==='withdrawn'?'retired':''}"><h3>${esc(r.status==='withdrawn'?c.withdrawal:c[r.type])}</h3>${[r.from,r.to].map(id=>{const x=claims.get(id);return x?`<p class="meta">${esc(sourceName(x.sourceId))}</p><blockquote>${esc(x.quote)}</blockquote>${sourceLink(x.sourceId)}`:'';}).join('')}</article>`).join('')}<p class="meta">${esc(c.scope)}</p></section>`:''}
<section class="panel"><h2>${esc(c.questions)}</h2>${result.questions.length?result.questions.map(q=>`<article class="question"><p>${esc(sourceName(q.sourceId))} — ${esc(q.kind==='time'?c.timeQuestion:c.sourceQuestion)}</p>${button('edit',c.edit,`data-id="${esc(q.sourceId)}"`)}</article>`).join('')+button('skip',c.skip):`<p class="meta">${esc(c.none)}</p>`}</section>
<section class="panel export"><h2>${esc(u.ready)}</h2><p>${esc(reviewed?m().reviewed:m().reviewNeeded)}</p><div class="toolbar">${button('mark-reviewed',m().review,reviewed||busy?'disabled':'')}${button('handoff',m().handoff,!reviewed||busy?'disabled':'')}${button('print',u.print,!reviewed||busy?'disabled':'')}${button('copy',u.copy,!reviewed||busy?'disabled':'')}</div></section>`}`;}
function render(){const c=t(),u=p();document.documentElement.lang=c.locale;document.title=`Care Notes · ${u.title}`;
root.innerHTML=`<main><header><a class="brand" href="./index.html">CARE NOTES</a><label class="language"><span class="sr-only">${esc(c.language)}</span><select id="lab-language" aria-label="${esc(c.language)}">${Object.entries(labels).map(([code,name])=>`<option value="${code}" ${lang===code?'selected':''}>${name}</option>`).join('')}</select></label></header>
<div class="workspace-switch">${button('own',m().own,`aria-pressed="${mode==='own'}" ${busy?'disabled':''}`)}${button('demo',m().demo,`aria-pressed="${mode==='demo'}" ${busy?'disabled':''}`)}</div>
<div class="intro"><h1>${esc(u.title)}</h1><p>${esc(u.subtitle)}</p>${mode==='demo'?`<span class="mode">${esc(['model','openai'].includes(method())?m().demo+' · '+c.live:demoModified?m().demo+' · '+c.local:c.demo)}</span>`:''}</div>
<nav class="app-nav" aria-label="Care Notes">${['capture','review','settings'].map((name,i)=>button(name,`${i+1}  ${u[name]}`,`aria-current="${tab===name?'page':'false'}"`)).join('')}</nav>
<div id="workspace-content">${tab==='capture'?capture():tab==='review'?review():`${settings()}<section class="panel"><h2>${esc(u.help)}</h2>${u.guide.map(([heading,body])=>`<details><summary>${esc(heading)}</summary><p>${esc(body)}</p></details>`).join('')}<p><a href="./records.html">${esc(u.legacy)}</a></p></section><section class="panel"><h2>${esc(m().backup)}</h2><p>${esc(u.backupHelp)}</p><p class="meta">${esc(mode==='demo'?m().exampleOnly:storageOK?m().saved:m().storageFailed)}</p><div class="toolbar">${button('download',m().backup)}<label class="button">${esc(m().restore)}<input id="restore" type="file" accept=".json,application/json" ${busy?'disabled':''}></label>${mode==='own'?button('clear',m().clear,`class="danger" ${busy?'disabled':''}`):''}${broken?button('broken',m().backup):''}</div></section><p class="meta">${esc(u.about)}</p>`}</div><footer>${esc(m().privacy)}</footer></main><pre id="print-sheet"></pre>`;
}
async function modelRequest(checking){if(busy)return;if(checking?!testConsent:!sendConsent){notice(checking?m().testConsent:p().sendConsent);return;}if(!checking&&(!checked||hasEdits())){notice(hasEdits()?m().pendingEdits:m().testFirst);return;}if(!checking&&ledger.analyses.length>=100){notice(m().errors.too_large);return;}
const selected={...connection};try{selected.provider==='custom'?customConnection(selected):connectionConfig(selected);}catch{notice(m().errors.invalid_connection);return;}
const sources=checking?CONNECTION_SAMPLE:activeSources(ledger),snapshot=revision;busy=true;controller=new AbortController();const callController=controller,timeout=setTimeout(()=>callController.abort(),65000);notice(t().busy);render();
try{let body;if(direct()){const answer=await reconstructOnDevice(sources,{...selected,fetchImpl:deviceFetch,signal:callController.signal,maxOutputTokens:checking?2000:6000});body=checking?assertConnectionSample(answer):answer;}else{const response=await fetch(checking?'./api/mobile/check':'./api/mobile/reconstruct',{method:'POST',headers:{'Content-Type':'application/json','X-Care-Notes':'mobile-ai'},body:JSON.stringify({connection:selected,consent:true,...(checking?{}:{sources})}),signal:callController.signal});body=await response.json();if(!response.ok)throw Error(body.error||'analysis_failed');}
if(snapshot!==revision){notice(t().stale);return;}if(checking){if(body.checked!==true)throw Error('check_failed');checked=true;saveConnection();notice(m().checked);}else{update(addAnalysis(ledger,body.proposal,{sources,method:'model'}));tab='review';notice(t().live);}}
catch(error){notice(callController.signal.aborted?p().cancelled:direct()&&error.message==='provider_network'?p().cors:m().errors[error.message]||m().errors.analysis_failed);}finally{clearTimeout(timeout);controller=null;busy=false;testConsent=false;sendConsent=false;render();}}
function handoff(){if(!reviewed||hasEdits()){notice(m().pendingEdits);return null;}return handoffText(ledger,t(),timeLabel);}
function switchMode(next){if(next===mode){route(next==='demo'?'review':'capture');return;}if(hasEdits()&&!confirm(p().exit))return;persist();mode=next;if(mode==='demo'&&!demoModified){example=demoLedger(lang);sampleLang=lang;}ledger=mode==='own'?own:example;result=reconstruct(ledger);changes=null;corrected=false;reviewed=false;sendConsent=false;questionLimit=3;revision++;clearDrafts();route(mode==='demo'?'review':'capture');}
root.addEventListener('click',async event=>{const source=event.target.closest('[data-source]');if(source){event.preventDefault();tab='capture';render();document.getElementById('source-'+source.dataset.source)?.scrollIntoView({block:'start'});return;}const b=event.target.closest('button[data-action]');if(!b||b.disabled)return;try{switch(b.dataset.action){
case 'capture':case 'review':case 'settings':route(b.dataset.action);break;
case 'own':case 'demo':if(!busy)switchMode(b.dataset.action);break;
case 'test':await modelRequest(true);break;
case 'analyse':await modelRequest(false);break;
case 'stop':controller?.abort();break;
case 'disconnect':connection.apiKey='';resetConsent();render();break;
case 'edit':editing=b.dataset.id;tab='capture';render();document.getElementById('source-'+editing)?.scrollIntoView({block:'center'});root.querySelector('#edit-source textarea')?.focus();break;
case 'cancel':delete drafts[editing];editing='';render();break;
case 'delete':{if(!confirm(p().deleteConfirm))return;const s=activeSources(ledger).find(s=>s.id===b.dataset.id);update(removeSource(ledger,s.id,s.version));break;}
case 'correct':if(busy)return;corrected=true;update(correctDemoDate(ledger,sampleLang));notice(t().stateSaved);break;
case 'reset':if(busy||demoModified&&!confirm(t().resetConfirm))return;ledger=demoLedger(lang);sampleLang=lang;example=ledger;result=reconstruct(ledger);changes=null;corrected=false;demoModified=false;questionLimit=3;reviewed=false;sendConsent=false;clearDrafts();revision++;render();break;
case 'skip':questionLimit=0;result=reconstruct(ledger,{questionLimit});render();break;
case 'mark-reviewed':if(hasEdits()){notice(m().pendingEdits);return;}reviewed=true;render();break;
case 'handoff':{const text=handoff();if(text)saveFile(text,'care-notes-handoff.txt','text/plain;charset=utf-8');break;}
case 'copy':{const text=handoff();if(text){try{if(isAndroid())globalThis.CareNotesNative.copyText(text);else await navigator.clipboard.writeText(text);notice(p().copied);}catch{notice(p().copyFailed);}}break;}
case 'print':{const text=handoff();if(text){document.getElementById('print-sheet').textContent=text;isAndroid()?globalThis.CareNotesNative.printPage():window.print();}break;}
case 'download':saveFile(workspaceJSON(ledger),'care-notes-workspace.json','application/json');break;
case 'broken':if(broken)saveFile(broken,'care-notes-recovery.json','application/json');break;
case 'clear':if(!confirm(m().clearConfirm))return;try{localStorage.removeItem(WORKSPACE_KEY);ownRaw='';broken='';storageOK=true;}catch{storageOK=false;}clearDrafts();update(createLedger());break;
}}catch(error){notice(m().errors[error.message]||t().failed);}});
root.addEventListener('submit',event=>{if(!['add-source','edit-source'].includes(event.target.id))return;event.preventDefault();const form=new FormData(event.target),text=form.get('text')?.trim();if(!text)return;try{if(event.target.id==='edit-source'){const id=event.target.dataset.id,s=activeSources(ledger).find(s=>s.id===id);const next=reviseSource(ledger,id,{text},s.version);delete drafts[id];editing='';update(next);}else{const next=addSource(ledger,{id:`e-${crypto.randomUUID()}`,text,author:form.get('author')?.trim()||m().unknownAuthor,recordedAt:localTimestamp()});delete drafts.new;delete drafts.author;update(next);}notice(mode==='demo'?m().exampleOnly:storageOK?p().local:m().storageFailed);}catch(error){notice(m().errors[error.message]||t().failed);}});
root.addEventListener('input',event=>{const el=event.target;if(el.matches('textarea')){const form=el.closest('form');drafts[form.dataset.id||'new']=el.value;reviewed=false;}if(el.name==='author')drafts.author=el.value;const key={'api-key':'apiKey',model:'model','base-url':'baseUrl'}[el.id];if(key){connection[key]=el.value.trim();resetConsent();for(const id of ['test-consent','send-consent']){const box=root.querySelector('#'+id);if(box)box.checked=false;}const dest=root.querySelector('#destination');if(dest)dest.textContent=m().destination+': '+destination();if(key!=='apiKey')saveConnection();}});
root.addEventListener('change',async event=>{const el=event.target;if(el.id==='test-consent')testConsent=el.checked;if(el.id==='send-consent')sendConsent=el.checked;if(el.id==='provider'){connection={provider:el.value,apiKey:'',model:'',...(el.value==='custom'?{baseUrl:'',format:'chat'}:{})};resetConsent();saveConnection();render();}if(el.id==='api-format'){connection.format=el.value;resetConsent();saveConnection();render();}if(el.id==='lab-language'){lang=el.value;setPref('care-notes.lang',lang);if(mode==='demo'&&!demoModified){sampleLang=lang;ledger=demoLedger(lang);example=ledger;result=reconstruct(ledger);}testConsent=false;sendConsent=false;render();}if(el.id==='restore'&&el.files[0]){const file=el.files[0];if(file.size>4000000){notice(m().badBackup);return;}try{const next=restoreWorkspace(await file.text());if(!confirm(m().restoreConfirm))return;mode='own';clearDrafts();broken='';ownRaw=readPref(WORKSPACE_KEY,'');update(next);route('capture');notice(storageOK?p().local:m().storageFailed);}catch{notice(m().badBackup);}}});
window.addEventListener('beforeunload',event=>{if(hasEdits()||busy){event.preventDefault();event.returnValue='';}});
window.addEventListener('pagehide',()=>{connection.apiKey='';resetConsent();controller?.abort();});
window.addEventListener('pageshow',event=>{if(event.persisted)render();});
window.addEventListener('care-notes-back',()=>{if(tab!=='capture'){route('capture');return;}if((hasEdits()||busy)&&!confirm(p().exit))return;connection.apiKey='';controller?.abort();globalThis.CareNotesNative?.closeApp();});
render();
if(!isAndroid()){fetch('./api/mobile/status',{cache:'no-store'}).then(r=>r.ok?r.json():{}).then(body=>{configured=body.available===true;if(tab==='settings'&&!busy)render();}).catch(()=>{});if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});}
